[Collection("macOS Window globals")]
public sealed class CssMixedAxisSizingTests:IDisposable
{
    private readonly RenderContext _context=RenderContext.GetOrCreateCurrent(RenderBackend.Metal);
    public void Dispose()=>_context.Dispose();
    public static IEnumerable<object[]> GeometryCases(){foreach(var c in Cases)yield return [c.Name];}
    [Theory] [MemberData(nameof(GeometryCases))]
    public void IndefiniteAndAllocatedDimensionsKeepTheirOwnPercentageRules(string name)
    {
        using var f=new MixedFixture(Cases.Single(c=>c.Name==name));f.Layout();
        var actual=f.Geometry();foreach(var pair in f.Case.Expected!)Near(pair.Value,actual[pair.Key]);
        Assert.Same(f.Percent??f.Leaf,f.Item.Child);
        if(f.Box is Panel panel)Assert.Same(f.Item,panel.Children[0]);else Assert.Same(f.Item,((Border)f.Box).Child);
        Assert.True(f.Root.IsMeasureValid);Assert.True(f.Root.IsArrangeValid);
    }
    [Theory] [InlineData("block")] [InlineData("flex")] [InlineData("grid")]
    public void ContentAndDefiniteContainerChangesRestoreTheMinimum(string display)
    {
        var c=Cases.Single(c=>c.Name=="block-auto-calc") with {Box="display:"+display+";width:200px;align-items:flex-start;"};
        using var f=new MixedFixture(c);f.Layout();Near(display=="grid"?150:100,f.Item.ActualHeight);
        f.Leaf.Height=140;f.Layout();Near(display=="grid"?170:140,f.Item.ActualHeight);
        Css.SetStyle(f.Box,c.Box+"height:200px;");f.Layout();Near(200,f.Item.ActualHeight);
        f.Item.MinHeight=0;f.Layout();Near(140,f.Item.ActualHeight);
        f.Item.ClearValue(FrameworkElement.MinHeightProperty);f.Layout();Near(200,f.Item.ActualHeight);
        Css.SetStyle(f.Box,c.Box);f.Layout();Near(display=="grid"?170:140,f.Item.ActualHeight);
        f.Leaf.Height=20;f.Layout();Near(display=="grid"?150:100,f.Item.ActualHeight);
    }
    [Theory] [InlineData(false)] [InlineData(true)]
    public void NativeAndAnimatedMinimaOverrideTheExpressionAndRestoreIt(bool horizontal)
    {
        using var f=new MixedFixture(Cases.Single(c=>c.Name=="block-auto-calc"));
        var property=horizontal?FrameworkElement.MinWidthProperty:FrameworkElement.MinHeightProperty;
        Css.SetStyle(f.Box,"display:inline-block;");Css.SetStyle(f.Item,"display:block;min-"+(horizontal?"width":"height")+":calc(100px + 50%);");
        f.Layout();Near(horizontal?150:100,horizontal?f.Item.ActualWidth:f.Item.ActualHeight);
        f.Item.SetValue(property,60d);f.Layout();Near(60,horizontal?f.Item.ActualWidth:f.Item.ActualHeight);
        f.Item.SetAnimatedValue(property,80d,false);f.Layout();Near(80,horizontal?f.Item.ActualWidth:f.Item.ActualHeight);
        f.Item.ClearAnimatedValue(property);f.Layout();Near(60,horizontal?f.Item.ActualWidth:f.Item.ActualHeight);
        f.Item.ClearValue(property);f.Layout();Near(horizontal?150:100,horizontal?f.Item.ActualWidth:f.Item.ActualHeight);
    }
    [Theory] [InlineData("calc(100px + 50%)",100)] [InlineData("calc(100px + 0%)",100)]
    [InlineData("max(60px, 30%)",60)] [InlineData("clamp(80px, 50%, 140px)",80)]
    public void AnUnboundedNativeMeasureRetainsTheLengthPartOfEachMinimum(string value,double expected)
    {
        var leaf=new Border{Width=40,Height=20};var item=new Border{Child=leaf};
        Css.SetStyle(item,"min-width:"+value+";min-height:"+value+";");Dispatcher.CurrentDispatcher.ProcessQueue();
        item.Measure(new(double.PositiveInfinity,double.PositiveInfinity));Near(expected,item.DesiredSize.Width);Near(expected,item.DesiredSize.Height);
        item.Child=null;
    }
    [Theory] [InlineData(false)] [InlineData(true)]
    public void UnboundedNativeEdgesRetainLengthsAndResolveAgainWhenBounded(bool margin)
    {
        var item=new Border{Child=new Border{Width=40,Height=20}};
        Css.SetStyle(item,(margin?"margin":"padding")+":calc(10px + 10%);");Dispatcher.CurrentDispatcher.ProcessQueue();
        item.Measure(new(double.PositiveInfinity,double.PositiveInfinity));Near(60,item.DesiredSize.Width);Near(40,item.DesiredSize.Height);
        item.Measure(new(200,double.PositiveInfinity));Near(100,item.DesiredSize.Width);Near(80,item.DesiredSize.Height);
        item.Measure(new(double.PositiveInfinity,double.PositiveInfinity));Near(60,item.DesiredSize.Width);Near(40,item.DesiredSize.Height);item.Child=null;
    }
    [Theory] [InlineData("flex",false)] [InlineData("flex",true)] [InlineData("grid",false)] [InlineData("grid",true)]
    public void EqualNativeGapOverridesInvalidateLayoutAndRestoreThePercentage(string layout,bool mixed)
    {
        using var f=new MixedFixture(Cases.Single(c=>c.Name=="native-"+layout+"-100px-"+(mixed?"calc(20px + 10%)":"10%")));
        var property=layout=="flex"?FlexPanel.RowSpacingProperty:Grid.RowSpacingProperty;var length=mixed?20d:0d;
        f.Layout();Near(30+length,f.Second!.TransformToAncestor(f.Box).Y);
        for(var i=0;i<2;i++)
        {
            f.Box.SetValue(property,length);f.Layout();Near(20+length,f.Second.TransformToAncestor(f.Box).Y);
            f.Box.SetAnimatedValue(property,5d,false);f.Layout();Near(25,f.Second.TransformToAncestor(f.Box).Y);
            f.Box.ClearAnimatedValue(property);f.Layout();Near(20+length,f.Second.TransformToAncestor(f.Box).Y);
            f.Box.ClearValue(property);f.Layout();Near(30+length,f.Second.TransformToAncestor(f.Box).Y);
        }
    }
    [Theory] [InlineData(false)] [InlineData(true)]
    public void StretchedAndStartAlignedFlexDescendantsReceiveDifferentHeightBases(bool native)
    {
        var root=new StackPanel();Panel flex=native?new FlexPanel():new StackPanel();var leaf=new Border{Width=40,Height=20};var percent=new Border{Child=leaf};var item=new Border{Child=percent};var tall=new Border{Width=40,Height=100};root.Children.Add(flex);flex.Children.Add(item);flex.Children.Add(tall);
        Css.SetStyle(item,"display:block;");Css.SetStyle(root,"display:block;width:400px;");Css.SetStyle(flex,"display:flex;align-items:flex-start;width:200px;");Css.SetStyle(percent,"display:block;height:50%;");
        Layout(root);Near(20,item.ActualHeight);Near(20,percent.ActualHeight);
        Css.SetStyle(flex,"display:flex;align-items:stretch;width:200px;");Layout(root);Near(100,item.ActualHeight);Near(50,percent.ActualHeight);
        Css.SetStyle(flex,"display:flex;align-items:flex-start;width:200px;height:160px;");Layout(root);Near(20,item.ActualHeight);Near(20,percent.ActualHeight);
        Css.SetStyle(item,"display:block;height:50%;");Layout(root);Near(80,item.ActualHeight);Near(40,percent.ActualHeight);
        flex.Children.Clear();root.Children.Clear();
    }
    [Fact]
    public void RestoringInheritedDirectionRebuildsAnonymousTextFragments()
    {
        var root=new StackPanel();var leaf=new Border{Height=44};var body=new TextBlock{FontFamily="PingFang SC",FontSize=16,LineHeight=24};var run=new Run("原文记录始终保留");body.Inlines.Add(run);leaf.Child=body;root.Children.Add(leaf);
        Css.SetStyle(body,"display:block;");Css.SetStyle(root,"display:block;width:300px;direction:ltr;");Layout(root);
        var initial=body.DocumentTextBounds(0,run.Text.Length)[0];
        Css.SetStyle(root,"display:block;width:300px;direction:rtl;");VisualTreeHelper.SetRootDpi(root,new(2,2));Layout(root);
        Assert.True(body.DocumentTextBounds(0,run.Text.Length)[0].X>initial.X+50,$"initial={initial}; rtl={body.DocumentTextBounds(0,run.Text.Length)[0]}; direction={root.FlowDirection}/{leaf.FlowDirection}/{body.FlowDirection}");
        Css.SetStyle(root,"display:block;width:300px;direction:ltr;");VisualTreeHelper.SetRootDpi(root,new(1,1));Layout(root);
        Near(initial.X,body.DocumentTextBounds(0,run.Text.Length)[0].X);Assert.Same(run,body.Inlines[0]);
        root.Children.Clear();leaf.Child=null;
    }
